class LRU:
    def __init__(self, cap: int):
        self.cap = cap
        self.cache = {}
    def get(self, k: int) -> int:
        if k not in self.cache: return -1
        v = self.cache.pop(k)
        self.cache[k] = v
        return v
    def put(self, k: int, v: int) -> None:
        if k in self.cache:
            self.cache[k] = v
            return
        if len(self.cache) >= self.cap:
            oldest = next(iter(self.cache))
            del self.cache[oldest]
        self.cache[k] = v

