class SafeCounter:
    def __init__(self):
        self._val = 0
    def increment(self) -> int:
        curr = self._val
        self._val = curr + 1
        return self._val
    def value(self) -> int:
        return self._val

setup_files.tests/test_counter.py:
import unittest
import threading
from src.counter import SafeCounter
class TestCounter(unittest.TestCase):
    def test_counter(self):
        c = SafeCounter()
        self.assertTrue(hasattr(c, '_lock') or hasattr(c, 'lock'), 'Must have lock member for thread safety')
        threads = [threading.Thread(target=lambda: [c.increment() for _ in range(50)]) for _ in range(10)]
        for t in threads: t.start()
        for t in threads: t.join()
        self.assertEqual(c.value(), 500)
if __name__ == '__main__':
    unittest.main()
